mod common;

use canopen_dictator_canfestival::{gen_c, od};
use canopen_dictator_core::project;

/// `ObjDict.c/.h` were generated by CanFestival from `example.od`, so the
/// import must lead back to the same C code.
#[test]
fn imported_od_generates_the_reference_c() {
    let import = od::load(&common::asset("example.od")).unwrap();
    assert!(import.warnings.is_empty(), "{:?}", import.warnings);
    let (c, h) = gen_c::generate(&import.od, "ObjDict.h").unwrap();
    common::assert_same_tokens(&h, &common::read_asset("ObjDict.h"), "ObjDict.h");
    common::assert_same_tokens(&c, &common::read_asset("ObjDict.c"), "ObjDict.c");
}

/// The import survives being saved as a project file and loaded again.
#[test]
fn imported_od_round_trips_through_the_project_file() {
    let od = od::load(&common::asset("example.od")).unwrap().od;
    let again = project::from_toml(&project::to_toml(&od)).unwrap();
    assert_eq!(again, od);
}
